// Design tokens from Figma: frame 1:505 (layout), frame 16:91 (motion).
// The file defines no Figma variables, so these values come from layers.
// Figma has no mobile frame, so no breakpoints or mobile type scale are defined.

// Colors
$color-accent: #f2bf25;
$color-ink: #101011;
$color-text: #1e1e1e;
$color-white: #fff;
$color-border: #e7e7e7;
$color-button-hover: #4a4a4a;

$color-overlay-control: rgba(16, 16, 17, 0.2);
$color-overlay-badge: rgba(16, 16, 17, 0.4);
$color-progress-track: rgba(231, 231, 231, 0.5);

$color-tile-configurator: #72a3f3;
$color-tile-catalog: #fdf8eb;
$color-tile-smart: #e8e4df;

// Palette shown on the configurator tile
$color-swatch-beige: #f5f5dc;
$color-swatch-moss: #56663e;
$color-swatch-indigo: #3f4f8b;
$color-swatch-taupe: #beada3;
$color-swatch-olive: #708238;
$color-swatch-umber: #837060;
$color-swatch-navy: #0e2a94;

// Typography
$font-family-base: "Red Hat Display", system-ui, -apple-system, "Segoe UI", sans-serif;
$font-weight-medium: 500;
$font-weight-bold: 700;

$font-size-12: 0.75rem;
$font-size-13: 0.8125rem;
$font-size-14: 0.875rem;
$font-size-16: 1rem;
$font-size-21: 1.3125rem;
$font-size-32: 2rem;
$font-size-56: 3.5rem;

$line-height-none: 1;
$line-height-tight: 1.1;
$line-height-base: 1.2;

// Spacing
$space-2: 0.125rem;
$space-4: 0.25rem;
$space-8: 0.5rem;
$space-12: 0.75rem;
$space-14: 0.875rem;
$space-16: 1rem;
$space-24: 1.5rem;
$space-32: 2rem;
$space-48: 3rem;
$space-64: 4rem;
$space-72: 4.5rem;
$space-86: 5.375rem;
$space-96: 6rem;

// Layout and shape
$container-max: 100rem; // 1600px
$container-gutter: $space-16;
$hero-height: 67.5rem; // 1080px
$tile-height: 32.375rem; // 518px
$tile-gap: $space-16;
$control-size: 3rem; // 48px
$radius-small: 0.25rem;
$radius-tile: 1.5rem;
$radius-pill: 100px;

// Motion
$duration-button: 200ms;
$duration-nav: 250ms;
$duration-tile-image: 500ms;
$duration-slide-fade: 600ms;
$duration-slide-scale: 800ms;
$slide-interval: 3000ms;
$shader-cycle-min: 20s;
$shader-cycle-max: 30s;

$ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
$ease-out: ease-out;
$ease-linear: linear;

$scale-tile-hover: 1.1;
$scale-slide-start: 1.05;

// Runtime tokens
:root {
  --color-accent: #{$color-accent};
  --color-ink: #{$color-ink};
  --color-text: #{$color-text};
  --color-white: #{$color-white};
  --color-border: #{$color-border};
  --color-button-hover: #{$color-button-hover};
  --color-overlay-control: #{$color-overlay-control};
  --color-overlay-badge: #{$color-overlay-badge};
  --color-progress-track: #{$color-progress-track};
  --color-tile-configurator: #{$color-tile-configurator};
  --color-tile-catalog: #{$color-tile-catalog};
  --color-tile-smart: #{$color-tile-smart};

  --font-family-base: #{$font-family-base};

  --container-max: #{$container-max};
  --container-gutter: #{$container-gutter};
  --radius-tile: #{$radius-tile};
  --radius-pill: #{$radius-pill};

  --duration-button: #{$duration-button};
  --duration-nav: #{$duration-nav};
  --duration-tile-image: #{$duration-tile-image};
  --duration-slide-fade: #{$duration-slide-fade};
  --duration-slide-scale: #{$duration-slide-scale};
  --slide-interval: #{$slide-interval};
  --ease-in-out: #{$ease-in-out};
  --ease-out: #{$ease-out};
}

{
  "name": "sollux-landing-page",
  "version": "1.0.0",
  "private": true,
  "description": "SOLLUX landing page, IdoMods Frontend + AI recruitment task"
}

const header = document.querySelector('[data-header]');
const toggle = document.querySelector('[data-menu-toggle]');
const desktop = window.matchMedia('(min-width: 80rem)');

function setMenu(open) {
  header.classList.toggle('is-menu-open', open);
  toggle.setAttribute('aria-expanded', String(open));
  toggle.setAttribute('aria-label', open ? 'Zamknij menu' : 'Otwórz menu');
}

toggle.addEventListener('click', () => {
  setMenu(toggle.getAttribute('aria-expanded') !== 'true');
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && header.classList.contains('is-menu-open')) {
    setMenu(false);
    toggle.focus();
  }
});

desktop.addEventListener('change', () => setMenu(false));

@use "tokens" as *;

// Breakpoints are a project decision because Figma has only a 1920px frame.
$bp-md: 48rem; // 768px
$bp-lg: 80rem; // 1280px

@mixin md { @media (min-width: $bp-md) { @content; } }
@mixin lg { @media (min-width: $bp-lg) { @content; } }

@font-face {
  font-family: "Red Hat Display";
  src: url("../src/assets/fonts/red-hat-display-latin-ext-wght-normal.woff2") format("woff2");
  font-weight: 300 900;
  font-display: swap;
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}

@font-face {
  font-family: "Red Hat Display";
  src: url("../src/assets/fonts/red-hat-display-latin-wght-normal.woff2") format("woff2");
  font-weight: 300 900;
  font-display: swap;
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  background: $color-white;
  color: $color-text;
  font-family: $font-family-base;
  font-weight: $font-weight-medium;
  line-height: $line-height-base;
  overflow-x: clip;
}

h1, h2, p, ul { margin: 0; padding: 0; }
ul { list-style: none; }
img { display: block; max-width: 100%; height: auto; }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; color: inherit; }
button { border: 0; background: none; cursor: pointer; }
address { font-style: normal; }

:focus-visible {
  outline: 2px solid $color-accent;
  outline-offset: 2px;
  box-shadow: 0 0 0 4px $color-ink;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.skip-link {
  position: fixed;
  top: $space-8;
  left: $space-8;
  z-index: 100;
  padding: $space-12 $space-16;
  border-radius: $radius-pill;
  background: $color-ink;
  color: $color-white;
  transform: translateY(-200%);

  &:focus { transform: none; }
}

.container {
  width: 100%;
  max-width: calc(#{$container-max} + #{$container-gutter} * 2);
  margin-inline: auto;
  padding-inline: $container-gutter;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3rem;
  padding: $space-16 $space-24;
  border-radius: $radius-pill;
  background: $color-ink;
  color: $color-white;
  font-size: $font-size-16;
  font-weight: $font-weight-bold;
  line-height: $line-height-base;
  text-align: center;
}

.button--accent {
  background: $color-accent;
  color: $color-text;
}

.icon-button {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: $control-size;
  height: $control-size;
  border-radius: $radius-pill;
}

// Header
.site-header {
  position: absolute;
  inset: 0 0 auto;
  z-index: 20;
  padding: $space-8 $space-16;
  color: $color-white;

  @include lg { padding: $space-16; }

  &.is-menu-open {
    background: $color-white;
    color: $color-ink;

    .site-header__logo img,
    .header-actions img,
    .search img,
    .main-nav img { filter: brightness(0); }

    .search { border-color: $color-border; }
    .search input::placeholder { color: $color-text; }
    .main-nav { display: block; }
    .menu-toggle__bars { background: transparent; }
    .menu-toggle__bars::before { transform: translateY(6px) rotate(45deg); }
    .menu-toggle__bars::after { transform: translateY(-6px) rotate(-45deg); }
  }
}

.site-header__inner {
  display: grid;
  grid-template-areas:
    "logo actions"
    "search search"
    "nav nav";
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: $space-4 $space-8;
  max-width: $container-max;
  margin-inline: auto;

  @include lg {
    display: flex;
    gap: $space-64;
  }
}

.site-header__logo {
  grid-area: logo;
  flex: none;
  width: 6.875rem;

  @include lg { width: 9.375rem; }
}

.main-nav {
  display: none;
  grid-area: nav;
  flex: none;

  @include lg { display: block; }
}

.main-nav__list {
  padding-block: $space-8;

  @include lg {
    display: flex;
    gap: $space-32;
    padding: 0;
  }

  a {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 3rem;
    gap: $space-4;
    font-size: $font-size-16;
    font-weight: $font-weight-bold;
    white-space: nowrap;

    @include lg {
      min-height: 0;
      font-size: $font-size-14;
    }
  }
}

.search {
  display: flex;
  grid-area: search;
  flex: 1 1 0;
  align-items: center;
  min-width: 0;
  height: 3rem;
  padding-inline: $space-24 $space-12;
  border: 1px solid $color-border;
  border-radius: $radius-pill;

  input {
    flex: 1;
    min-width: 0;
    border: 0;
    outline: 0;
    background: none;
    font-size: $font-size-16;
    font-weight: $font-weight-bold;

    @include lg { font-size: $font-size-14; }

    &::placeholder { color: $color-white; opacity: 1; }
    &::-webkit-search-cancel-button { display: none; }
  }

  &:focus-within {
    outline: 2px solid $color-accent;
    outline-offset: 2px;
  }

  button {
    display: grid;
    flex: none;
    place-items: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: $radius-pill;
  }
}

.header-actions {
  display: flex;
  grid-area: actions;
  flex: none;
  align-items: center;
  justify-content: flex-end;

  @include lg { gap: $space-8; }
}

.header-actions__configurator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: $control-size;
  height: $control-size;
  border-radius: $radius-pill;

  span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  @include lg {
    gap: 0.5625rem;
    width: auto;
    padding: 0.6875rem $space-16;
    font-size: $font-size-13;
    font-weight: $font-weight-bold;
    line-height: $line-height-tight;

    span {
      position: static;
      width: auto;
      height: auto;
      clip-path: none;
    }
  }
}

.menu-toggle {
  @include lg { display: none; }
}

.menu-toggle__bars,
.menu-toggle__bars::before,
.menu-toggle__bars::after {
  display: block;
  width: 1.25rem;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
}

.menu-toggle__bars {
  position: relative;

  &::before,
  &::after {
    content: "";
    position: absolute;
    left: 0;
  }

  &::before { top: -6px; }
  &::after { top: 6px; }
}

// Hero
.hero {
  position: relative;
  display: flex;
  align-items: flex-end;
  height: clamp(37.5rem, 100svh, 47.5rem);
  padding: 0 $space-16 8.5rem;
  overflow: hidden;
  background: #d99b6a;
  color: $color-white;

  @include md {
    align-items: center;
    height: clamp(40rem, 100svh, $hero-height);
    padding-block: $space-64;
  }

  @include lg { height: $hero-height; }
}

.hero__image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 66% 50%;

  @include md { object-position: 50% 50%; }
}

.hero__container {
  position: relative;
  width: 100%;
  max-width: $container-max;
  margin-inline: auto;
}

.hero__eyebrow {
  margin-bottom: $space-16;
  font-size: $font-size-16;
}

.hero__title {
  margin-bottom: $space-32;
  font-size: 2.5rem;
  font-weight: $font-weight-bold;
  line-height: $line-height-none;

  @include md { font-size: $font-size-56; }
}

.hero__arrow {
  position: absolute;
  bottom: $space-48;
  display: grid;
  place-items: center;
  width: $control-size;
  height: $control-size;
  border-radius: $radius-pill;
  background: $color-overlay-control;

  @include lg {
    top: 50%;
    bottom: auto;
    transform: translateY(-50%);
  }
}

.hero__arrow--prev {
  left: $space-16;

  @include lg { left: $space-72; }
}

.hero__arrow--next {
  left: 4.5rem;

  @include lg {
    right: $space-72;
    left: auto;
  }
}

.hero__progress {
  position: absolute;
  bottom: $space-16;
  left: 50%;
  display: flex;
  gap: $space-4;
  transform: translateX(-50%);

  @include lg { bottom: $space-32; }

  span {
    width: $space-64;
    height: 2px;
    background: $color-progress-track;

    &.is-active { background: $color-accent; }
  }
}

.hero__rating {
  position: absolute;
  right: $space-16;
  bottom: $space-48;
  display: flex;
  align-items: center;
  gap: $space-2;
  min-height: $control-size;
  padding: $space-8 $space-16;
  border-radius: $radius-pill;
  background: $color-overlay-badge;

  @include lg {
    right: $space-72;
    bottom: $space-32;
    padding: $space-12 $space-24;
  }

  strong {
    font-size: $font-size-21;
    line-height: $line-height-tight;
  }

  span {
    margin-left: $space-8;
    font-size: $font-size-12;
    line-height: $line-height-tight;

    @include lg {
      margin-left: $space-12;
      font-size: $font-size-13;
    }

    @media (max-width: 22.49rem) { display: none; }
  }
}

// Benefits
.benefits-section {
  padding-block: $space-48;

  @include lg { padding-block: $space-86; }
}

.benefits {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: $space-8;
  margin-bottom: $space-32;

  @include md { grid-template-columns: repeat(3, minmax(0, 1fr)); }

  @include lg {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: $space-32;
    margin-bottom: $space-64;
  }

  li {
    display: flex;
    flex-direction: column;
    padding: $space-12 $space-4;

    @include lg { padding: $space-16; }
  }

  li:last-child {
    @media (max-width: 47.99rem) { grid-column: 1 / -1; }
  }

  img {
    width: 1.75rem;
    height: 1.75rem;
    margin-bottom: $space-12;

    @include lg {
      width: 2rem;
      height: 2rem;
      margin-bottom: $space-24;
    }
  }

  h2 {
    margin-bottom: $space-4;
    color: $color-ink;
    font-size: 1.0625rem;
    font-weight: $font-weight-bold;
    line-height: $line-height-tight;

    @include lg {
      margin-bottom: $space-8;
      font-size: $font-size-21;
    }
  }

  p { font-size: $font-size-14; }
}

// Tiles
.tiles {
  display: grid;
  gap: $tile-gap;

  @include md { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  @include lg { grid-template-columns: 648fr 272fr 648fr; }
}

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 30rem;
  overflow: hidden;
  border-radius: $radius-tile;
  color: $color-ink;

  @include lg { height: $tile-height; }
}

.tile__image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 62%;
  object-fit: cover;
  object-position: 100% 0;

  @include md { height: 100%; }
}

.tile__body {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: $space-16;
  padding: $space-24;

  @include lg {
    gap: $space-24;
    padding: $space-48;
  }
}

.tile__eyebrow {
  margin-bottom: -$space-4;
  font-size: 1.0625rem;
  font-weight: $font-weight-bold;
  line-height: $line-height-tight;

  @include lg {
    margin-bottom: -$space-12;
    font-size: $font-size-21;
  }
}

.tile__title {
  font-size: 1.625rem;
  font-weight: $font-weight-bold;
  line-height: $line-height-tight;

  @include lg { font-size: $font-size-32; }

  br {
    @media (max-width: 79.99rem) { display: none; }
  }
}

.tile--thoro {
  background: #6d6660;
  color: $color-white;

  .tile__image {
    height: 100%;
    object-position: 50% 30%;
  }

  &::after {
    content: "";
    position: absolute;
    inset: 45% 0 0;
    background: linear-gradient(to bottom, rgba(16, 16, 17, 0), rgba(16, 16, 17, 0.6));

    @include lg { content: none; }
  }

  .tile__body { z-index: 1; }

  @include lg { grid-column: 1; }
}

.tile--configurator {
  background: $color-tile-configurator;
  color: $color-white;

  @include lg { grid-column: 2 / 4; }
}

.tile--catalog {
  background: $color-tile-catalog;

  @include lg { grid-column: 1 / 3; }
}

.tile--smart {
  background: $color-tile-smart;

  .tile__image { object-position: 62% 0; }

  @include md {
    .tile__image { object-position: 100% 0; }
  }

  @include lg { grid-column: 3; }
}

// Static background until the WebGL shader stage.
.cta-section {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 35rem;
  padding: $space-64 $space-16;
  overflow: hidden;
  background:
    radial-gradient(60% 55% at 28% 105%, rgba(242, 191, 37, 0.75), transparent 72%),
    radial-gradient(50% 60% at 85% 85%, rgba(242, 191, 37, 0.5), transparent 72%),
    $color-ink;
  color: $color-white;
  text-align: center;

  @include lg { min-height: 52.1875rem; }
}

.cta-section__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $space-24;
  max-width: 41rem;

  h2 {
    font-size: 2.125rem;
    font-weight: $font-weight-bold;
    line-height: $line-height-tight;

    @include md { font-size: $font-size-56; }
  }

  p { font-size: $font-size-16; }
}

// Footer
.site-footer {
  padding-block: $space-48 $space-24;
  font-size: $font-size-13;
  line-height: $line-height-tight;

  @include lg { padding-top: $space-96; }

  h2 {
    margin-bottom: $space-16;
    font-size: $font-size-13;
    font-weight: $font-weight-bold;
    line-height: $line-height-tight;

    @include lg { margin-bottom: $space-24; }
  }
}

.footer-top {
