"""Render the page in exact-width iframes and report layout problems.
Usage: check_page.py <project> <outdir>"""
import functools, http.server, json, pathlib, subprocess, sys, threading

root, out = map(pathlib.Path, sys.argv[1:3])
out.mkdir(parents=True, exist_ok=True)
SIZES = ((320, 700), (390, 844), (768, 1024), (1024, 768), (1280, 800), (1920, 1080))


class Quiet(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def do_GET(self):
        if self.path.startswith("/__harness"):
            w, h = map(int, self.path.split("?")[1].split("x"))
            body = HARNESS.replace("__W__", str(w)).replace("__H__", str(h)).encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        super().do_GET()


HARNESS = """<!doctype html><title>pending</title><style>html,body{margin:0;background:#fff}iframe{border:0;display:block}</style>
<iframe id=f src="/index.html" width=__W__ height=__H__></iframe><script>
const f=document.getElementById('f');
f.onload=async()=>{const d=f.contentDocument,w=f.contentWindow;
d.querySelectorAll('img').forEach(i=>i.loading='eager');
await d.fonts.ready;
await Promise.all([...d.images].map(i=>i.complete?0:new Promise(r=>{i.onload=i.onerror=r})));
const cw=d.documentElement.clientWidth;
const bad=[...d.querySelectorAll('body *')].filter(e=>{const r=e.getBoundingClientRect();
 return r.width>0&&!e.closest('.visually-hidden,.skip-link')&&!e.matches('.hero__image,.tile__image')&&(r.right>cw+1||r.left<-1)})
 .slice(0,6).map(e=>e.tagName+'.'+(e.className||''));
const small=[...d.querySelectorAll('a,button')].filter(e=>{const r=e.getBoundingClientRect();
 return r.width>0&&!e.closest('.skip-link')&&(r.height<24||r.width<24)}).length;
const h=d.documentElement.scrollHeight;
const res={w:cw,sw:d.documentElement.scrollWidth,h,bad,small,
 font:d.fonts.check('700 16px "Red Hat Display"'),
 broken:[...d.images].filter(i=>!i.naturalWidth).map(i=>i.src.split('/').pop())};
f.height=h;
await new Promise(r=>setTimeout(r,250));
document.title=JSON.stringify(res)};
</script>"""

handler = functools.partial(Quiet, directory=str(root))
srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler)
port = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()

for w, h in SIZES:
    url = f"http://127.0.0.1:{port}/__harness?{w}x{h}"
    win = max(w, 500)
    r = subprocess.run(["chromium", "--headless=new", "--no-sandbox", "--disable-gpu", "--hide-scrollbars",
                        f"--window-size={win},{h}", "--virtual-time-budget=6000", "--dump-dom", url],
                       capture_output=True, text=True)
    t = r.stdout.split("<title>")[1].split("</title>")[0].replace("&quot;", '"')
    try:
        d = json.loads(t)
    except ValueError:
        print(w, "probe failed:", t[:100])
        continue
    print(f"{w}: scrollW={d['sw']} H={d['h']} font={d['font']} overflow={d['bad']} small_targets={d['small']} broken={d['broken']}")
    subprocess.run(["chromium", "--headless=new", "--no-sandbox", "--disable-gpu", "--hide-scrollbars",
                    f"--window-size={win},{d['h']}", "--virtual-time-budget=6000",
                    f"--screenshot={out}/page-{w}.png", url], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    if win != w:
        subprocess.run(["convert", f"{out}/page-{w}.png", "-crop", f"{w}x{d['h']}+0+0", "+repage", f"{out}/page-{w}.png"], check=True)
srv.shutdown()

