(() => {
  const hero = document.querySelector('[data-hero]');
  if (!hero) return;

  const slides = [...hero.querySelectorAll('[data-slide]')];
  const segments = [...hero.querySelectorAll('[data-segment]')];
  const lamps = [...hero.querySelectorAll('[data-lamp]')];
  const pauseButton = hero.querySelector('[data-pause]');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const finePointer = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  const pauseReasons = new Set();
  let current = 0;

  function setPaused(reason, paused) {
    if (paused) pauseReasons.add(reason);
    else pauseReasons.delete(reason);
    hero.classList.toggle('is-paused', pauseReasons.size > 0);
  }

  function syncLitState() {
    const anyLit = lamps.some((lamp) => lamp.getAttribute('aria-pressed') === 'true');
    slides[0].classList.toggle('is-lit', anyLit);
    setPaused('lit', anyLit && current === 0);
  }

  function goTo(index) {
    const next = (index + slides.length) % slides.length;
    if (next === current) return;

    slides.forEach((slide, i) => {
      slide.classList.toggle('is-active', i === next);
      slide.classList.remove('is-entering');
      slide.inert = i !== next;
    });
    void slides[next].offsetWidth; // Restarts the entrance animation.
    slides[next].classList.add('is-entering');
    segments.forEach((segment, i) => segment.classList.toggle('is-active', i === next));
    current = next;
    syncLitState();
  }

  hero.querySelector('[data-prev]').addEventListener('click', () => goTo(current - 1));
  hero.querySelector('[data-next]').addEventListener('click', () => goTo(current + 1));

  // The progress bar is the slider clock, so pausing it also pauses autoplay.
  hero.addEventListener('animationend', (event) => {
    if (event.animationName === 'hero-progress') goTo(current + 1);
  });

  lamps.forEach((lamp) => {
    lamp.addEventListener('click', () => {
      const on = lamp.getAttribute('aria-pressed') !== 'true';
      lamp.setAttribute('aria-pressed', String(on));
      lamp.setAttribute('aria-label', `${on ? 'Wyłącz' : 'Włącz'} ${lamp.dataset.lamp} lampę`);
      syncLitState();
    });
    lamp.addEventListener('pointerenter', (event) => {
      if (event.pointerType === 'mouse') setPaused('lamp-hover', true);
    });
    lamp.addEventListener('pointerleave', () => setPaused('lamp-hover', false));
  });

  hero.addEventListener('focusin', (event) => {
    if (event.target.matches(':focus-visible')) setPaused('focus', true);
  });
  hero.addEventListener('focusout', (event) => {
    if (!hero.contains(event.relatedTarget)) setPaused('focus', false);
  });
  document.addEventListener('visibilitychange', () => setPaused('hidden', document.hidden));

  if (!reducedMotion) {
    hero.classList.add('is-autoplay');
    pauseButton.hidden = false;
    pauseButton.addEventListener('click', () => {
      const paused = !pauseReasons.has('user');
      setPaused('user', paused);
      pauseButton.classList.toggle('is-stopped', paused);
      pauseButton.setAttribute(
        'aria-label',
        paused ? 'Wznów automatyczne przewijanie' : 'Zatrzymaj automatyczne przewijanie',
      );
    });
  }

  if (reducedMotion || !finePointer) return;

  // Lamps lean toward the cursor, each with its own depth.
  const states = lamps.map((element, i) => ({
    element,
    depth: [1, 0.65, 1.3][i],
    x: 0, y: 0, rotate: 0,
    targetX: 0, targetY: 0, targetRotate: 0,
  }));
  let frame = 0;

  function tick() {
    let moving = false;
    states.forEach((state) => {
      state.x += (state.targetX - state.x) * 0.09;
      state.y += (state.targetY - state.y) * 0.09;
      state.rotate += (state.targetRotate - state.rotate) * 0.09;
      if (Math.abs(state.targetX - state.x) + Math.abs(state.targetY - state.y)
        + Math.abs(state.targetRotate - state.rotate) > 0.01) moving = true;
      state.element.style.transform = `translate3d(${state.x.toFixed(2)}px, ${state.y.toFixed(2)}px, 0) rotate(${state.rotate.toFixed(2)}deg)`;
    });
    frame = moving ? requestAnimationFrame(tick) : 0;
  }

  function animate() {
    if (!frame) frame = requestAnimationFrame(tick);
  }

  hero.addEventListener('pointermove', (event) => {
    if (event.pointerType !== 'mouse') return;
    const bounds = hero.getBoundingClientRect();
    const stage = slides[0].getBoundingClientRect();
    const pointerX = event.clientX - bounds.left;
    const pointerY = event.clientY - bounds.top;
    const normalX = pointerX / bounds.width - 0.5;
    const normalY = pointerY / bounds.height - 0.5;

    states.forEach((state) => {
      const centerX = stage.left - bounds.left + state.element.offsetLeft + state.element.offsetWidth / 2;
      const lean = ((pointerX - centerX) / bounds.width) * 26;
      state.targetX = normalX * 44 * state.depth;
      state.targetY = normalY * 32 * state.depth;
      state.targetRotate = Math.max(-9, Math.min(9, lean));
    });
    animate();
  });

  hero.addEventListener('pointerleave', () => {
    states.forEach((state) => {
      state.targetX = 0;
      state.targetY = 0;
      state.targetRotate = 0;
    });
    animate();
  });
})();

(() => {
  const canvas = document.querySelector('[data-shader]');
  if (!canvas) return;

  const CYCLE_MS = 25000;
  const FRAME_MS = 1000 / 30;
  const STATIC_PHASE = 0.12;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const vertexSource = `
    attribute vec2 position;
    void main() { gl_Position = vec4(position, 0.0, 1.0); }
  `;

  // Time only moves points around closed circles, so phase 1 equals phase 0.
  const fragmentSource = `
    #ifdef GL_FRAGMENT_PRECISION_HIGH
    precision highp float;
    #else
    precision mediump float;
    #endif

    uniform vec2 resolution;
    uniform float phase;

    const float TAU = 6.28318530718;
    const vec3 INK = vec3(0.0627, 0.0627, 0.0667);
    const vec3 AMBER = vec3(0.36, 0.26, 0.05);
    const vec3 GOLD = vec3(0.949, 0.749, 0.145);

    float hash(vec2 p) {
      vec3 q = fract(vec3(p.xyx) * 0.1031);
      q += dot(q, q.yzx + 33.33);
      return fract((q.x + q.y) * q.z);
    }

    float noise(vec2 p) {
      vec2 cell = floor(p);
      vec2 f = fract(p);
      vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
      return mix(
        mix(hash(cell), hash(cell + vec2(1.0, 0.0)), u.x),
        mix(hash(cell + vec2(0.0, 1.0)), hash(cell + vec2(1.0, 1.0)), u.x),
        u.y
      );
    }

    float fbm(vec2 p) {
      float value = 0.0;
      float amplitude = 0.55;
      for (int i = 0; i < 3; i++) {
        value += amplitude * noise(p);
        p = mat2(1.6, 1.2, -1.2, 1.6) * p + vec2(3.1, 1.7);
        amplitude *= 0.48;
      }
      return value;
    }

    vec2 orbit(float turns, float offset) {
      float angle = TAU * (phase * turns + offset);
      return vec2(cos(angle), sin(angle));
    }

    void main() {
      vec2 uv = gl_FragCoord.xy / resolution;
      float aspect = resolution.x / resolution.y;
      vec2 p = vec2(uv.x * aspect, uv.y);
      vec2 tilted = mat2(0.88, -0.47, 0.47, 0.88) * p;

      vec2 warp = vec2(
        fbm(tilted * 1.1 + 0.42 * orbit(1.0, 0.0)),
        fbm(tilted * 1.1 + vec2(5.2, 1.3) + 0.42 * orbit(1.0, 0.33))
      );
      float flow = fbm(tilted * 0.9 + 1.5 * warp + 0.24 * orbit(2.0, 0.6));

      float wave = sin(tilted.x * 4.4 + flow * 6.4 + 0.7 * sin(TAU * phase));
      float folds = smoothstep(0.05, 0.98, 0.5 + 0.5 * wave);
      float rise = smoothstep(0.84, 0.02, uv.y + 0.34 * (flow - 0.5));
      float light = folds * rise;

      vec2 center = (uv - vec2(0.5, 0.52)) * vec2(1.25, 1.9);
      light *= mix(0.46, 1.0, smoothstep(0.12, 0.72, length(center)));

      vec3 color = mix(INK, AMBER, smoothstep(0.0, 0.5, light));
      color = mix(color, GOLD, smoothstep(0.38, 1.0, light));
      color += (hash(gl_FragCoord.xy) - 0.5) / 255.0;
      gl_FragColor = vec4(color, 1.0);
    }
  `;

  const gl = canvas.getContext('webgl', {
    alpha: false,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'low-power',
  });
  if (!gl) return; // The CSS gradient stays as a fallback.

  let uniforms = null;
  let elapsed = 0;
  let lastTime = 0;
  let lastDraw = -Infinity;
  let frame = 0;
  let inView = false;

  function compile(type, source) {
    const shader = gl.createShader(type);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    return gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? shader : null;
  }

  function setup() {
    const vertex = compile(gl.VERTEX_SHADER, vertexSource);
    const fragment = compile(gl.FRAGMENT_SHADER, fragmentSource);
    if (!vertex || !fragment) return false;

    const program = gl.createProgram();
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return false;
    gl.useProgram(program);

    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const position = gl.getAttribLocation(program, 'position');
    gl.enableVertexAttribArray(position);
    gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

    uniforms = {
      resolution: gl.getUniformLocation(program, 'resolution'),
      phase: gl.getUniformLocation(program, 'phase'),
    };
    return true;
  }

  function draw(phase) {
    if (!uniforms) return;
    gl.uniform2f(uniforms.resolution, canvas.width, canvas.height);
    gl.uniform1f(uniforms.phase, phase);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    canvas.classList.add('is-ready');
  }

  function currentPhase() {
    return reducedMotion ? STATIC_PHASE : (elapsed % CYCLE_MS) / CYCLE_MS;
  }

  function resize() {
    // Soft gradients stay smooth at a reduced internal resolution.
    const bounds = canvas.getBoundingClientRect();
    const scale = Math.min(0.75, 960 / Math.max(bounds.width, 1));
    const width = Math.max(1, Math.round(bounds.width * scale));
    const height = Math.max(1, Math.round(bounds.height * scale));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
      gl.viewport(0, 0, width, height);
    }
    draw(currentPhase());
  }

  function render(now) {
    frame = requestAnimationFrame(render);
    elapsed += Math.min(now - lastTime, 250);
    lastTime = now;
    if (now - lastDraw < FRAME_MS) return;
    lastDraw = now;
    draw(currentPhase());
  }

  function updateLoop() {
    const shouldRun = inView && !document.hidden && !reducedMotion && uniforms;
    if (shouldRun && !frame) {
      lastTime = performance.now();
      frame = requestAnimationFrame(render);
    } else if (!shouldRun && frame) {
      cancelAnimationFrame(frame);
      frame = 0;
    }
  }

  canvas.addEventListener('webglcontextlost', (event) => {
    event.preventDefault();
    uniforms = null;
    canvas.classList.remove('is-ready');
    updateLoop();
  });

  canvas.addEventListener('webglcontextrestored', () => {
    if (setup()) {
      gl.viewport(0, 0, canvas.width, canvas.height);
      draw(currentPhase());
    }
    updateLoop();
  });

  if (!setup()) return;

  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    inView = entry.isIntersecting;
    updateLoop();
  }, { rootMargin: '100px' }).observe(canvas);
  document.addEventListener('visibilitychange', updateLoop);
})();

