// Soft circular highlight and icon micro-interactions.
.header-actions .icon-button,
.header-actions__configurator {
  position: relative;
  isolation: isolate;

  &::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: $radius-pill;
    background: currentColor;
    opacity: 0;
    transform: scale(0.82);
    transition:
      opacity $duration-button $ease-in-out,
      transform $duration-nav $ease-out;
  }
}

@mixin header-action-active {
  &::before {
    opacity: 0.1;
    transform: scale(1);
  }
}

.header-actions .icon-button:focus-visible,
.header-actions__configurator:focus-visible { @include header-action-active; }

@media (hover: hover) and (pointer: fine) {
