1	import { copyFile, mkdir, readFile, rm, stat } from 'node:fs/promises';
2	import path from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	
5	const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
6	const output = path.join(root, '_site');
7	const isLocal = (url) => url && !url.startsWith('#') && !/^[a-z][a-z0-9+.-]*:/i.test(url) && !url.startsWith('//');
8	const clean = (url) => url.split(/[?#]/)[0];
9	
10	function resolveInsideProject(base, url) {
11	  const file = path.resolve(base, clean(url));
12	  if (file !== root && !file.startsWith(root + path.sep)) {
13	    throw new Error(`Reference points outside the project: ${url}`);
14	  }
15	  return file;
16	}
17	
18	const html = await readFile(path.join(root, 'index.html'), 'utf8');
19	const files = new Set([path.join(root, 'index.html')]);
20	
21	for (const [, url] of html.matchAll(/\b(?:src|href)="([^"]*)"/g)) {
22	  if (isLocal(url)) files.add(resolveInsideProject(root, url));
23	}
24	
25	for (const [, value] of html.matchAll(/\bsrcset="([^"]*)"/g)) {
26	  for (const candidate of value.split(',')) {
27	    const url = candidate.trim().split(/\s+/)[0];
28	    if (isLocal(url)) files.add(resolveInsideProject(root, url));
29	  }
30	}
31	
32	for (const file of [...files].filter((name) => name.endsWith('.css'))) {
33	  const css = await readFile(file, 'utf8');
34	  for (const [, url] of css.matchAll(/url\(\s*["']?([^"')]+)["']?\s*\)/g)) {
35	    if (isLocal(url)) files.add(resolveInsideProject(path.dirname(file), url));
36	  }
37	}
38	
39	await rm(output, { recursive: true, force: true });
40	
41	let bytes = 0;
42	for (const file of files) {
43	  const { size } = await stat(file);
44	  const target = path.join(output, path.relative(root, file));
45	  await mkdir(path.dirname(target), { recursive: true });
46	  await copyFile(file, target);
47	  bytes += size;
48	}
49	
50	console.log(`Built _site: ${files.size} files, ${(bytes / 1024 / 1024).toFixed(2)} MB`);
51

