"""Produce a cleaned JSONL copy of a Claude Code session.
Usage: clean_transcript.py <raw.jsonl> <out.jsonl>
Prints only counts, never the removed values."""
import json, re, sys, collections

src, dst = sys.argv[1:3]
stats = collections.Counter()

ALLOWED_EMAILS = {"noreply@anthropic.com", "git@github.com", "sklep@sollux.pl"}
RULES = [
    # signed / expiring Figma asset links
    (re.compile(r"https://www\.figma\.com/api/mcp/asset/[\w-]+"), "[usunieto: link do assetu Figma]"),
    # SSH key material and fingerprints
    (re.compile(r"ssh-ed25519 [A-Za-z0-9+/=]+"), "ssh-ed25519 [usunieto: klucz publiczny]"),
    (re.compile(r"SHA256:[A-Za-z0-9+/=]{20,}"), "SHA256:[usunieto]"),
    # tokens, just in case
    (re.compile(r"\b(gh[pousr]_|figd_|sk-ant-)[A-Za-z0-9_-]{10,}"), "[usunieto: token]"),
    # local paths (longest first)
    (re.compile(r"/tmp/claude-\d+/[^\s\"'\\]*?/scratchpad"), "<scratchpad>"),
    (re.compile(r"/tmp/claude-\d+/[^\s\"'\\]*"), "<tmp>"),
    (re.compile(r"/home/[a-z_][\w-]*/Desktop/landing_page"), "<projekt>"),
    (re.compile(r"/home/[a-z_][\w-]*/\.claude/projects/[\w.-]+"), "<katalog-sesji>"),
    (re.compile(r"/home/[a-z_][\w-]*"), "~"),
    (re.compile(r"-home-[a-z_][\w-]*-Desktop-landing-page"), "<katalog-sesji>"),
    # all UUIDs: session, Figma session, organisation, asset ids
    (re.compile(r"\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b"), "<uuid>"),
    # phone numbers
    (re.compile(r"\+48[\d ]{9,12}\d"), "[usunieto: telefon]"),
    # full personal name of the author (first name alone stays, it is public in git history)
    (re.compile(r"(?i)marcin\s+[autor]"), "[autor]"),
    # long numeric account ids (Figma user/team ids)
    (re.compile(r"\b\d{16,20}\b"), "<id>"),
]
EMAIL = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")


def scrub(text):
    for rx, rep in RULES:
        text, n = rx.subn(rep, text)
        stats["rule:" + rep] += n
    def mail(m):
        if m.group(0).rstrip(".") in ALLOWED_EMAILS or re.match(r"[\w-]+@\d", m.group(0)):
            return m.group(0)
        stats["email"] += 1
        return "[usunieto: e-mail]"
    return EMAIL.sub(mail, text)


def deep(v):
    if isinstance(v, str):
        return scrub(v)
    if isinstance(v, list):
        return [deep(x) for x in v]
    if isinstance(v, dict):
        return {k: deep(x) for k, x in v.items()}
    return v


def clean_block(b, whoami_ids):
    t = b.get("type")
    if t == "image":
        stats["images"] += 1
        return {"type": "text", "text": "[usunieto: obraz (zrzut ekranu)]"}
    if t == "thinking":
        return {"type": "thinking", "thinking": b.get("thinking", "")}
    if t == "redacted_thinking":
        return {"type": "text", "text": "[ukryte rozumowanie modelu]"}
    if t == "tool_use":
        if b.get("name") == "mcp__figma__whoami":
            whoami_ids.add(b.get("id"))
        return {"type": "tool_use", "id": b.get("id"), "name": b.get("name"), "input": b.get("input")}
    if t == "tool_result":
        out = {"type": "tool_result", "tool_use_id": b.get("tool_use_id")}
        if b.get("is_error"):
            out["is_error"] = True
        if b.get("tool_use_id") in whoami_ids:
            stats["whoami"] += 1
            out["content"] = "[usunieto: dane konta Figma zwrocone przez whoami]"
            return out
        c = b.get("content")
        out["content"] = [clean_block(x, whoami_ids) for x in c] if isinstance(c, list) else c
        return out
    return b


whoami_ids = set()
kept = 0
with open(src) as f, open(dst, "w") as g:
    for line in f:
        o = json.loads(line)
        if o.get("type") not in ("user", "assistant", "system"):
            stats["dropped:" + str(o.get("type"))] += 1
            continue
        msg = o.get("message")
        rec = {k: o[k] for k in ("type", "uuid", "parentUuid", "timestamp", "isCompactSummary", "isMeta", "subtype") if k in o}
        if isinstance(msg, dict):
            m = {k: msg[k] for k in ("role", "model") if k in msg}
            c = msg.get("content")
            m["content"] = [clean_block(b, whoami_ids) for b in c] if isinstance(c, list) else c
            rec["message"] = m
        elif "content" in o:
            rec["content"] = o["content"]
        rec = deep(rec)
        g.write(json.dumps(rec, ensure_ascii=False) + "\n")
        kept += 1

print("kept records:", kept)
for k, v in sorted(stats.items()):
    print(f"{v:6}  {k}")

