    secrets.setdefault("user e-mail", set()).update(re.findall(r"[\w.+-]+@gmail\.com", ctx))
for blob in re.findall(r'\\"whoami\\":\{.*?\}\]', raw)[:1]:
    for k in ("user_id", "handle", "email", "key"):
        secrets.setdefault("figma " + k, set()).update(v for v in re.findall(r'\\"%s\\":\\"([^\\"]+)' % k, blob))
