    "<uuid>", "<uuid>"}
secrets["uuid (full)"] = uuids
secrets["uuid prefix"] = {u[:8] for u in uuids}
secrets["ssh key"] = set(re.findall(r"ssh-ed25519 (AAAA[A-Za-z0-9+/=]{20,})", raw))
secrets["ssh fingerprint"] = set(re.findall(r"SHA256:([A-Za-z0-9+/=]{20,})", raw))
home = os.path.expanduser("~")
secrets["home path"] = {home + "/"}
secrets["tmp path"] = {"/tmp/claude-" + str(os.getuid()) + "/-"}
secrets["phone (spaced)"] = set(re.findall(r"\d{3}[\s ]\d{3}[\s ]\d{3}", raw))
secrets["surname"] = {"mi" + "truk", "jaku" + "bik"}

bad = 0
for name, vals in secrets.items():
